b.addEventListener('click',()=>{
      if(submitted)return;submitted=true;good=b.dataset.tourAnswer==='correct';answerLabel=b.textContent.replace(/^[A-C]\.\s*/, '').trim();
      const answerButtons=[...stack.querySelectorAll('.answer')];answerButtons.filter(x=>x!==b).forEach(x=>{x.disabled=true;x.setAttribute('aria-hidden','true');x.classList.add('answer-exit');setTimeout(()=>x.classList.add('hidden'),motionAllowed()?180:0)});
      const host=document.createElement('div');host.className='confidence-host tour-real-confidence';host.setAttribute('role','group');host.setAttribute('aria-labelledby','tourConfidenceLabel');
      host.innerHTML=`<div class="tour-selected-answer">Your answer: <strong>${esc(answerLabel)}</strong></div><div class="confidence-copy"><span id="tourConfidenceLabel">How sure were you?</span><button class="context-tip-icon" type="button" id="tourConfidenceWhy" aria-label="Why does StudyGrid ask this?">?</button></div><div class="confidence-choices"><button data-tour-confidence="0">Guessing</button><button data-tour-confidence="1">Fairly sure</button><button data-tour-confidence="2">Very sure</button><button data-tour-confidence="skip">Skip</button></div>`;
      b.replaceWith(host);
      result.innerHTML='<strong>Now choose your confidence.</strong>It helps choose what to practise next. It does not change whether your answer was correct.';
      host.querySelector('#tourConfidenceWhy')?.addEventListener('click',()=>{result.innerHTML='<strong>Why ask this?</strong>Confidence and correctness are separate signals. A confident miss and a low-confidence correct answer can both deserve another look.'});
      host.querySelectorAll('[data-tour-confidence]').forEach(x=>x.addEventListener('click',()=>finishDemo(x.dataset.tourConfidence)));
      host.querySelector('[data-tour-confidence]')?.focus({preventScroll:true});playUiSound('press');
    })

