document.getElementById('contributionForm').addEventListener('submit',e=>{
    e.preventDefault();
    const file=document.getElementById('contribFile').files[0];
    state.contributions.forEach(x=>delete x.justAdded);
    const item={id:'contrib-'+Date.now(),courseId:c.id,type:document.getElementById('contribType').value,title:document.getElementById('contribTitle').value.trim(),fileName:file?.name||'',context:document.getElementById('contribContext').value.trim(),createdAt:new Date().toISOString(),status:'Received',justAdded:true};
    if(!item.title)return;
    state.contributions.push(item);
    if(persist('contribution record created')){announce('Contribution record created. The file itself was not uploaded.');renderContribute(c,main)}
  })

